const pattern = /\[([^\]]+)\]\(([^)]+)\)|<([a-zA-Z][a-zA-Z0-9+.-]*:[^>\s]+)>/g;
for (const m of String(inputs.markdown).matchAll(pattern)) {
  if (m[1] && m[2]) links.push({ url: m[2], title: includeTitles ? m[1] : "" });
  else if (m[3]) links.push({ url: m[3], title: "" });
}
return { output: links };

